import{_ as i,l as r,o as e,c as s,v as t,p as l,x as o,d as c,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"贝尔曼方程","description":"","frontmatter":{"title":"贝尔曼方程","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bellman-equation.md","filePath":"econ/bellman-equation.md","lastUpdated":1789023840000}'),p={name:"econ/bellman-equation.md"};function E(h,a,_,u,v,B){const n=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="贝尔曼方程" tabindex="-1">贝尔曼方程 <a class="header-anchor" href="#贝尔曼方程" aria-label="Permalink to &quot;贝尔曼方程&quot;">​</a></h1><div class="epigraph"><p>动态最优的值满足：今天的回报加折扣后的续值，再对当前行动取最大；不动点是值函数，不是状态路径。</p><footer>—— 据 Stokey, Lucas and Prescott, Recursive Methods in Economic Dynamics, 1989, 第 4 章；Bellman, Dynamic Programming, 1957 整理</footer></div><p>上一课<a href="/econ/uhc-correspondence">上半连续对应</a>用 Berge 保证「今天这一步最大化」的值连续、最优对应 UHC。动态问题是一串这样的步骤。缺口是把无穷期（或有限期向后）收成一个函数方程 \\(v=Tv\\)，而不是在序列空间里对整条 \\(\\{x_t\\}\\) 做一次静态优化。后课 Ramsey、搜寻、随机增长都默认会写贝尔曼；本课只补方程本身与它和压缩的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态 \\(s\\in S\\)，行动 \\(a\\in\\Gamma(s)\\)，回报 \\(F(s,a)\\)，转移 \\(s&#39;=g(s,a)\\)（随机情形则对条件分布取期望，那是后课<a href="/econ/conditional-expectation-econ">条件期望</a>的接口）。值函数 \\(v(s)=\\sup_{\\{a_t\\}} \\sum_{t=0}^\\infty \\beta^t F(s_t,a_t)\\)。 在正则条件下 \\(v\\) 满足 \\(v(s)=\\max_{a\\in\\Gamma(s)}\\{F(s,a)+\\beta v(g(s,a))\\}\\)。 右端定义算子 \\((Tv)(s)=\\max_a\\{F+\\beta v\\circ g\\}\\)。贝尔曼方程即 \\(v=Tv\\)。有限期则从终端值向后递推，没有不动点问题；无穷期折扣 \\(\\beta\\lt 1\\) 才用压缩。</p><p>序列问题与函数方程的等价不是自动的：要有限回报、可行计划非空、可测选择。Stokey–Lucas–Prescott 把这些写成假设清单。本课不逐条证等价，只标明：写出 \\(v=Tv\\) 之后，还要用压缩（或单调性）确认 \\(T\\) 的不动点就是序列问题的值。</p><h3 id="贝尔曼不是欧拉方程" tabindex="-1">贝尔曼不是欧拉方程 <a class="header-anchor" href="#贝尔曼不是欧拉方程" aria-label="Permalink to &quot;贝尔曼不是欧拉方程&quot;">​</a></h3><p>欧拉方程是内部解对 \\(a\\) 的 FONC，连接 \\(v&#39;(s)\\) 与 \\(v&#39;(s&#39;)\\)（包络再给 \\(v&#39;\\)）。它是贝尔曼的一阶条件，假定内点、可微。角点、不可微、离散行动只有贝尔曼，没有欧拉。后课<a href="/econ/consumption-euler">跨期消费与欧拉方程</a>会从贝尔曼推欧拉；本课禁止把两者当同一句话。</p><p><span class="marginnote">\\(\\beta=1\\) 的未折扣问题可以没有有限值，或要 overtaking 准则。主干宏观折扣 \\(\\beta\\lt 1\\)。平均报酬、最优增长的无界回报用加权范数，仍是压缩家族，不是另一套哲学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 \\(C(S)\\)（\\(S\\) 紧）上，若 \\(F\\) 连续、\\(\\Gamma\\) 连续紧值，Berge 推出 \\(T:C(S)\\to C(S)\\)。Blackwell：单调加折扣 \\(\\Rightarrow\\) \\(T\\) 是模 \\(\\beta\\) 的压缩。于是唯一连续值函数，最优对应 UHC（再加凸结构则凸值）。策略 \\(a^*(s)\\in\\arg\\max\\) 生成的计划达到 \\(v\\)——这要用可测选择，有限 \\(S\\) 或连续且单值时自动。</p><p>随机情形把 \\(v(g(s,a))\\) 换成 \\(\\mathbb{E}[v(s&#39;)\\mid s,a]\\)。期望是对已知条件分布的积分，信息结构用 \\(\\sigma\\)-代数描述是后一单元的事。本课只要求：把续值换成条件期望后，若期望保连续与单调，压缩论证原样搬。</p>',12)),(e(),l(d,null,{default:o(()=>[m(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%BA%8F%E5%88%97%E9%97%AE%E9%A2%98%EF%BC%9A%E5%AF%B9%E6%95%B4%E6%9D%A1%E8%B7%AF%E5%BE%84%E6%B1%82%E5%80%BC%22%5D%20--%3E%20V%5B%22%E5%80%BC%E5%87%BD%E6%95%B0%20v(s)%22%5D%0A%20%20V%20--%3E%20T%5B%22%E8%B4%9D%E5%B0%94%E6%9B%BC%E7%AE%97%E5%AD%90%20T%22%5D%0A%20%20T%20--%3E%20FP%5B%22v%20%E7%AD%89%E4%BA%8E%20T%20v%22%5D%0A%20%20FP%20--%3E%20POL%5B%22%E7%AD%96%E7%95%A5%20argmax%22%5D%0A%20%20POL%20--%3E%20EULER%5B%22%E5%86%85%E7%82%B9%E6%97%B6%E6%8E%A8%E5%87%BA%E6%AC%A7%E6%8B%89%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最优性原理：无论今天如何到达 \\(s\\)，余下计划必须对从 \\(s\\) 出发的子问题最优。否则把子计划换成更好的，总折现回报上升。于是无穷期最优可以递归：今天只选 \\(a\\)，明天交给已经最优的 \\(v\\)。压缩保证这个递归有唯一解，不会因「无穷多个明天」而漂。</p><p>包络：\\(v&#39;(s)=F_s+\\beta v&#39;(s&#39;)g_s\\) 在内点成立，状态的边际值等于直接边际回报加续值的边际。这是上一单元包络在动态上的实例。比较静态对稳态资本求导，常常走这条，而不是对整个序列变分。</p><p><span class="marginnote">时间不一致（双曲线折扣、承诺）破坏「余下问题仍用同一个 \\(v\\)」。那不是贝尔曼算错，是偏好在时间上换了算子。后课<a href="/econ/time-inconsistency">时间不一致与承诺</a>再对照。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲连续时间 HJB、黏性解，不把随机控制写成 Itô 讲义——量化栏才走 SDE。也不把 Ramsey 模型在这里展开：只准备方程。下一课把 \\(T\\) 的 Picard 迭代写成算法：值函数迭代。</p><p>后课默认：折扣动态规划写成 \\(v=Tv\\)；\\(T\\) 在连续有界函数上是压缩；欧拉是内点特例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贝尔曼方程：\\(v=Tv\\)，今天回报加折扣续值再最大化。</li><li>最优性原理把序列问题收成函数不动点。</li><li>连续紧、Berge、Blackwell \\(\\Rightarrow\\) 唯一连续 \\(v\\)。</li><li>欧拉是内部一阶条件，不是方程本身。</li><li>下一课：<a href="/econ/value-function-iteration">值函数迭代</a>。</li><li>出处：Stokey, Lucas and Prescott 第 4 章；Bellman, <em>Dynamic Programming</em>。</li></ul>',9))])}const A=i(p,[["render",E]]);export{b as __pageData,A as default};
